mapper.select:
/* 自动回补 */ select d.bookset_id as booksetId, /*账套代码*/ d.layering_id as layeringId, /*分层代码*/ DATE_FORMAT(d.happen_date, '%Y-%m-%d') as happenDate, /*入账日期*/ d.fee_type as feeType, /*费用类型*/ d.clawback_amt as clawbackAmt, /*回补金额*/ #{anapleroticType02} as clawbackType /*回补方式*/ from BOK_CLAWBACK_INFO_DETAIL d inner join BOK_CLAWBACK_INFO info on d.bookset_id = info.bookset_id and d.layering_id = info.layering_id and d.happen_date = info.happen_date and d.book_date = info.book_date where info.clawback_type = #{anapleroticType02}
AND d.bookset_id = #{booksetId}
AND d.happen_date between STR_TO_DATE(#{startDate}, '%Y-%m-%d') and STR_TO_DATE(#{endDate}, '%Y-%m-%d')
UNION ALL
/* 手动回补 */ select deal.bookset_id as booksetId, /*账套代码*/ lay.layering_id as layeringId, /*分层代码*/ DATE_FORMAT(trd.trade_date, '%Y-%m-%d')as happenDate, /*入账日期*/ trd.finprod_type as feeType, /*费用类型*/ trd.int_amt as clawbackAmt, /*回补金额*/ #{anapleroticType01} as clawbackType /*回补方式*/ from TRD_PRODUCT_DEAL trd inner join BOK_DEAL_ACCOUNTING deal on trd.trade_id = deal.busi_no inner join FIN_CASH_INFO cash on trd.finprod_id = cash.cash_id inner join BOK_ACCT_LAYERING_INFO lay on deal.bookset_id = lay.bookset_id and cash.finprod_id = lay.busi_id and cash.branch = lay.branch where trd.BUSI_TYPE = #{busiType}
AND deal.bookset_id = #{booksetId}
AND trd.trade_date between STR_TO_DATE(#{startDate}, '%Y-%m-%d') and STR_TO_DATE(#{endDate}, '%Y-%m-%d')
